  -- Three-level (with Brand): "Sweetwater Integration~Blackmagic~Videohub 12G"
  Name         = "Sweetwater Integration~Blackmagic~Videohub 12G",
  Version      = "0.1.0",
  BuildVersion = "0.1.0.0",
  Id           = "<guid>",
  Author       = "Sweetwater Integration",
  Description  = "Control for Blackmagic Videohub 12G routers (Mini 4x2 through 80x80)"
}

function GetColor(props)
  return { 0, 134, 214 }
end

function GetPrettyName(props)
